                i = end + 1
        elif c == "\\" and i + 1 < n:
            out.append(re.escape(pat[i + 1]))
            i += 2
        else:
            out.append(re.escape(c))
            i += 1
    return "".join(out)


def _find_class_end(pat, start):
    n = len(pat)
    j = start + 1
    if j < n and pat[j] == "!":
        j += 1
    if j < n and pat[j] == "]":
        j += 1
    while j < n:
        if pat[j] == "\\" and j + 1 < n:
            j += 2
        elif pat[j] == "]":
            return j
        else:
            j += 1
    return -1


def _translate_class(content):
    negative = content.startswith("!")
    if negative:
        content = content[1:]
    out = ["[^/" if negative else "["]
    i = 0
    while i < len(content):
        c = content[i]
        if c == "\\" and i + 1 < len(content):
            nxt = content[i + 1]
            if nxt in r"\]^-":
                out.append("\\" + nxt)
            else:
                out.append(re.escape(nxt))
            i += 2
        elif c == "\\":
            out.append(r"\\")
            i += 1
        elif c == "]":
            out.append(r"\]")
            i += 1
        else:
            out.append(c)
            i += 1
    out.append("]")
    return "".join(out)

