        line = raw[:-1] if raw.endswith("\r") else raw
        if not line or line[0] == "#":
            continue
        line = _strip_trailing_spaces(line)
        if not line:
            continue
        negate = False
        if line[0] == "!":
            negate = True
            line = line[1:]
            if not line:
                continue
        compiled, dir_only = _compile(line)
        patterns.append((compiled, dir_only, negate))
    return patterns


def _strip_trailing_spaces(line):
    """Strip trailing spaces unless escaped with an odd run of backslashes."""
    i = len(line)
    while i > 0 and line[i - 1] == " ":
        bs = 0
        j = i - 2
        while j >= 0 and line[j] == "\\":
            bs += 1
            j -= 1
        if bs % 2 == 1:
            break
        i -= 1
    return line[:i]


def _compile(pattern):
    """Compile a gitignore pattern (after `!` strip) to (regex, dir_only)."""
    had_leading = pattern.startswith("/")
    if had_leading:
        pattern = pattern[1:]
    dir_only = pattern.endswith("/")
    if dir_only:
        pattern = pattern[:-1]
    anchored = had_leading or ("/" in pattern)
    if not anchored:
        pattern = "**/" + pattern
    regex = _translate(pattern)
    return re.compile("^" + regex + "$"), dir_only


def _translate(pat):
    out = []
    i, n = 0, len(pat)
    while i < n:
        c = pat[i]
        if c == "*":
            if i + 1 < n and pat[i + 1] == "*":
                prev_sep = i == 0 or pat[i - 1] == "/"
                np = i + 2
                next_sep = np < n and pat[np] == "/"
                next_end = np == n
                if prev_sep and next_sep:
                    out.append("(?:.*/)?")
                    i = np + 1
                elif prev_sep and next_end:
                    out.append(".*")
                    i = np
                else:
                    out.append("[^/]*")
                    i += 2
            else:
                out.append("[^/]*")
                i += 1
        elif c == "?":
            out.append("[^/]")
            i += 1
        elif c == "[":
            end = _find_class_end(pat, i)
            if end == -1:
                out.append(re.escape("["))
                i += 1
            else:
                out.append(_translate_class(pat[i + 1:end]))
                i = end + 1
        elif c == "\\" and i + 1 < n:
            out.append(re.escape(pat[i + 1]))
            i += 2
        else:
            out.append(re.escape(c))
            i += 1
    return "".join(out)


def _find_class_end(pat, start):
    n = len(pat)
    j = start + 1
    if j < n and pat[j] == "!":
        j += 1
    if j < n and pat[j] == "]":
        j += 1
    while j < n:
        if pat[j] == "\\" and j + 1 < n:
            j += 2
        elif pat[j] == "]":
            return j
        else:
            j += 1
    return -1


def _translate_class(content):
    negative = content.startswith("!")
    if negative:
        content = content[1:]
    out = ["[^/" if negative else "["]
    i = 0
    while i < len(content):
        c = content[i]
        if c == "\\" and i + 1 < len(content):
            nxt = content[i + 1]
            if nxt in r"\]^-":
                out.append("\\" + nxt)
            else:
                out.append(re.escape(nxt))
            i += 2
        elif c == "\\":
            out.append(r"\\")
            i += 1
        elif c == "]":
            out.append(r"\]")
            i += 1
        else:
            out.append(c)
            i += 1
    out.append("]")
    return "".join(out)

